async function upsertCategories(){const m=new Map<string,string>();for(const c of C){const[e]=await db.select({id:categories.id}).from(categories).where(eq(categories.slug,c.slug)).limit(1);if(e){await db.update(categories).set({name:c.name,description:c.description,image:c.image,coverImage:c.coverImage,icon:c.icon,parentId:c.parentId,isActive:c.isActive,sortOrder:c.sortOrder,updatedAt:new Date()}).where(eq(categories.id,e.id));m.set(c.id,e.id)}else{const[n]=await db.insert(categories).values({name:c.name,slug:c.slug,description:c.description,image:c.image,coverImage:c.coverImage,icon:c.icon,parentId:c.parentId,isActive:c.isActive,sortOrder:c.sortOrder}).returning({id:categories.id});m.set(c.id,n.id)}}for(const c of C){if(c.parentId){const np=m.get(c.parentId),ni=m.get(c.id);if(np&&ni&&np!==c.parentId)await db.update(categories).set({parentId:np}).where(eq(categories.id,ni))}}return m}
async function upsertProducts(cm:Map<string,string>){const pm=new Map<string,string>();for(const p of P){const cid=cm.get(p.categoryId)??p.categoryId;const[e]=await db.select({id:products.id}).from(products).where(eq(products.sku,p.sku)).limit(1);const pl={name:p.name,slug:p.slug,description:p.description,shortDescription:p.shortDescription,specs:p.specs as any,price:p.price,comparePrice:p.comparePrice,cost:p.cost,images:p.images as any,categoryId:cid,stock:p.stock,lowStockThreshold:p.lowStockThreshold,sku:p.sku,barcode:p.barcode,weight:p.weight,rating:p.rating,reviewCount:p.reviewCount,tags:p.tags as any,condition:p.condition,featured:p.featured,isNew:p.isNew,isActive:p.isActive,brand:p.brand,updatedAt:new Date()}as any;if(e){await db.update(products).set(pl).where(eq(products.id,e.id));pm.set(p.id,e.id)}else{const[n]=await db.insert(products).values(pl).returning({id:products.id});pm.set(p.id,n.id)}}return pm}
async function upsertVariants(pm:Map<string,string>){for(const v of V){const pid=pm.get(v.productId)??v.productId;const[e]=await db.select({id:productVariants.id}).from(productVariants).where(eq(productVariants.sku,v.sku)).limit(1);const pl={productId:pid,name:v.name,sku:v.sku,price:v.price,stock:v.stock,attributes:v.attributes,image:v.image,isActive:v.isActive,sortOrder:v.sortOrder,updatedAt:new Date()}as any;if(e)await db.update(productVariants).set(pl).where(eq(productVariants.id,e.id));else await db.insert(productVariants).values(pl)}}
async function upsertRates(){for(const r of SR){const[e]=await db.select({state:shippingRates.state}).from(shippingRates).where(eq(shippingRates.state,r.state)).limit(1);if(e)await db.update(shippingRates).set({price:r.price,estimatedDays:r.estimatedDays,isActive:r.isActive,updatedAt:new Date()}).where(eq(shippingRates.state,r.state));else await db.insert(shippingRates).values(r)}}
async function upsertSettings(){for(const s of SS){const[e]=await db.select({key:siteSettings.key}).from(siteSettings).where(eq(siteSettings.key,s.key)).limit(1);if(e)await db.update(siteSettings).set({value:s.value,updatedAt:new Date()}).where(eq(siteSettings.key,s.key));else await db.insert(siteSettings).values(s)}}
async function upsertRaffles(){for(const r of RF){const e=await db.select({id:raffles.id}).from(raffles).where(eq(raffles.title,r.title)).limit(1);if(e.length===0)await db.insert(raffles).values({...r,drawDate:new Date(r.drawDate)})}}
async function upsertCoupons(){for(const c of CP){const[e]=await db.select({id:coupons.id}).from(coupons).where(eq(coupons.code,c.code)).limit(1);if(e)await db.update(coupons).set({...c,updatedAt:new Date()}as any).where(eq(coupons.id,e.id));else await db.insert(coupons).values(c as any)}}
async function main(){if(!process.env.DATABASE_URL)throw new Error('DATABASE_URL is missing');console.log('Upserting categories...');const cm=await upsertCategories();console.log('Upserting products...');const pm=await upsertProducts(cm);console.log('Upserting variants...');await upsertVariants(pm);console.log('Upserting shipping rates...');await upsertRates();console.log('Upserting site settings...');await upsertSettings();console.log('Upserting raffles...');await upsertRaffles();console.log('Upserting coupons...');await upsertCoupons();console.log('Seed complete: 48 categories, 81 products, 80 variants, 37 rates, 21 settings, 3 raffles, 3 coupons.')}
main().catch(e=>{console.error(e);process.exit(1)})